     PW::KLookAndFeel
     KNightTime
 )
diff --git a/kcms/lookandfeel/kded/lookandfeelautoswitcher.cpp b/kcms/lookandfeel/kded/lookandfeelautoswitcher.cpp
index df854bfbaf..f6bce24b03 100644
--- a/kcms/lookandfeel/kded/lookandfeelautoswitcher.cpp
+++ b/kcms/lookandfeel/kded/lookandfeelautoswitcher.cpp
@@ -11,9 +11,12 @@
 #include "lookandfeelautoswitcherstate.h"
 #include "lookandfeelsettings.h"

+#include <KGlobalAccel>
+#include <KLocalizedString>
 #include <KPackage/PackageLoader>
 #include <KPluginFactory>

+#include <QAction>
 #include <QDateTime>
 #include <QDebug>
 #include <algorithm>
@@ -30,6 +33,14 @@ LookAndFeelAutoSwitcher::LookAndFeelAutoSwitcher(QObject *parent, const QList<QV
 {
     connect(m_configWatcher.get(), &KConfigWatcher::configChanged, this, &LookAndFeelAutoSwitcher::onConfigChanged);

+    auto toggleAction = new QAction(this);
+    toggleAction->setObjectName(QStringLiteral("toggle dark mode"));
+    toggleAction->setText(i18nc("@action shortcut", "Toggle Dark Mode"));
+    toggleAction->setProperty("componentName", QStringLiteral("lookandfeel"));
+    toggleAction->setProperty("componentDisplayName", i18nc("@title Name for global shortcuts category", "Global Theme"));
+    KGlobalAccel::self()->setGlobalShortcut(toggleAction, QList<QKeySequence>());
+    connect(toggleAction, &QAction::triggered, this, &LookAndFeelAutoSwitcher::toggleDarkMode);
+
     reconfigure();
 }

@@ -138,6 +149,25 @@ void LookAndFeelAutoSwitcher::applyLookAndFeel(const QString &id)
     manager.save(package, selection);
 }

+void LookAndFeelAutoSwitcher::toggleDarkMode()
+{
+    const bool darkMode = m_settings->lookAndFeelPackage() == m_settings->defaultDarkLookAndFeel();
+    const QString id = darkMode ? m_settings->defaultLightLookAndFeel() : m_settings->defaultDarkLookAndFeel();
+
+    KPackage::Package package = KPackage::PackageLoader::self()->loadPackage(QStringLiteral("Plasma/LookAndFeel"));
+    package.setPath(id);
+    if (!package.isValid()) {
+        return;
+    }
+
+    m_settings->setAutomaticLookAndFeel(false);
+    m_settings->setLookAndFeelPackage(id);
+    m_settings->save();
+
+    KLookAndFeelManager manager;
+    manager.save(package, KLookAndFeelManager::AppearanceSettings | KLookAndFeelManager::BlendChanges);
+}
+
 void LookAndFeelAutoSwitcher::reschedule()
 {
     const QDateTime now = QDateTime::currentDateTime();
