@@ -39,6 +39,7 @@ private:

     QString lookAndFeelAtDateTime(const QDateTime &dateTime) const;
     void applyLookAndFeel(const QString &id);
+    void toggleDarkMode();

     std::unique_ptr<LookAndFeelSettings> m_settings;
     std::unique_ptr<LookAndFeelAutoSwitcherState> m_state;
